<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad, onPullDownRefresh } from '@dcloudio/uni-app'
import { distributionApi } from '../../api/distribution.api'
import type { DistributionFilterOption, UnfinishedDistributionItem } from '../../models/distribution'
import WareState from '@/shared/components/WareState.vue'
import SessionDatePicker from '@/shared/components/SessionDatePicker.vue'
import { sessionStore } from '@/store/session'

const date=ref(new Date().toISOString().slice(0,10)),zone=ref(''),draftZone=ref(''),zoneDrawerVisible=ref(false),zoneOptions=ref<DistributionFilterOption[]>([]),orderNum=ref(''),productName=ref(''),loading=ref(false),error=ref(''),list=ref<UnfinishedDistributionItem[]>([]),selected=ref<number[]>([]),action=ref<6|7>(6),drawerVisible=ref(false),remark=ref(''),submitting=ref(false)
const sessionPickerVisible=ref(false)
const selectedUnits=computed(()=>list.value.filter(item=>selected.value.includes(item.enterItemId)).reduce((sum,item)=>sum+item.unfinishedUnits,0))
const allSelected=computed(()=>list.value.length>0&&list.value.every(item=>selected.value.includes(item.enterItemId)))
const rankText=(rank:number)=>['','A','B','C','D','E'][rank]||`${rank}级`
async function load(){if(!sessionStore.can('distribution.unfinished.view'))return;loading.value=true;error.value='';try{list.value=await distributionApi.unfinishedItems(date.value,{zone:zone.value,orderNum:orderNum.value.trim(),productName:productName.value.trim()});selected.value=[]}catch(e){error.value=e instanceof Error?e.message:'未配货数据加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
async function loadZones(){zoneOptions.value=await distributionApi.filterOptions(date.value)}
function openZonePicker(){draftZone.value=zone.value;zoneDrawerVisible.value=true}
function confirmZone(){zone.value=draftZone.value;zoneDrawerVisible.value=false;load()}
async function changeSession(){zone.value='';await loadZones();await load()}
function toggle(id:number){selected.value=selected.value.includes(id)?selected.value.filter(value=>value!==id):[...selected.value,id]}
function toggleAll(){selected.value=allSelected.value?[]:list.value.map(item=>item.enterItemId)}
function openAction(value:6|7){if(!selected.value.length)return uni.showToast({title:'请先选择花材',icon:'none'});action.value=value;drawerVisible.value=true}
async function submit(){if(submitting.value)return;submitting.value=true;try{const result=await distributionApi.markShortage(selected.value,action.value,remark.value);drawerVisible.value=false;uni.showToast({title:`已处理${result.affectedUnits}扎`,icon:'success'});await load()}finally{submitting.value=false}}
onLoad(query=>{if(!sessionStore.can('distribution.unfinished.view')){uni.showToast({title:'当前账号无权查看未配货汇总',icon:'none'});setTimeout(()=>uni.navigateBack(),600);return}if(query?.date)date.value=String(query.date);loadZones();load()});onPullDownRefresh(load)
</script>

<template><view class="page">
  <view class="overview"><view><text>本场次未配货</text><strong>{{list.reduce((sum,item)=>sum+item.unfinishedUnits,0)}}</strong><small>扎</small></view><text class="session-trigger" @click="sessionPickerVisible=true">{{date}} 场次⌄</text></view>
  <view class="filters"><view class="search"><input v-model="orderNum" type="number" placeholder="货位号" confirm-type="search" @confirm="load"/></view><view class="search"><input v-model="productName" placeholder="花材名称" confirm-type="search" @confirm="load"/></view><view class="zone-filter" @click="openZonePicker">{{zone?(zoneOptions.find(item=>item.zone===zone)?.areaName||`${Number(zone)}区`):'全部分区'}}<text class="down"/></view></view>
  <view class="list-head"><view class="check" :class="{checked:allSelected}" @click="toggleAll">{{allSelected?'✓':''}}</view><text>花材与供应商</text><text>未配</text><text>货位</text></view>
  <WareState v-if="loading" type="loading" title="正在汇总未配货"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重新加载" @action="load"/>
  <view v-else-if="list.length" class="rows"><view v-for="item in list" :key="item.enterItemId" :class="['row',{selected:selected.includes(item.enterItemId)}]" @click="toggle(item.enterItemId)"><view class="check" :class="{checked:selected.includes(item.enterItemId)}">{{selected.includes(item.enterItemId)?'✓':''}}</view><view class="product"><strong>{{item.productName}}<text>{{rankText(item.rank)}}</text></strong><small>{{item.supplierName}} · ¥{{item.supplyPrice.toFixed(2)}}/扎</small></view><b>{{item.unfinishedUnits}}</b><view class="shelf"><strong>#{{item.shelfNo}}</strong><small>{{item.segment}}段</small></view></view></view>
  <WareState v-else type="empty" title="暂无未配货数据" description="当前筛选条件下的花材均已完成配货或处置"/>
  <view class="bottom"><view class="selection">已选 {{selected.length}} 项 · {{selectedUnits}} 扎</view><view class="actions"><button @click="openAction(6)">缺货补货</button><button class="danger" @click="openAction(7)">缺货不补</button></view></view>
  <view v-if="zoneDrawerVisible" class="mask" @click="zoneDrawerVisible=false"><view class="drawer zone-drawer" @click.stop><view class="zone-head"><strong>选择分区</strong><text @click="confirmZone">确定</text></view><scroll-view scroll-y class="zone-scroll"><view class="zone-grid"><view :class="{active:!draftZone}" @click="draftZone=''">全部分区</view><view v-for="item in zoneOptions" :key="item.zone" :class="{active:draftZone===item.zone}" @click="draftZone=item.zone">{{item.areaName||`${Number(item.zone)}区`}}</view></view></scroll-view></view></view>
  <view v-if="drawerVisible" class="mask" @click="drawerVisible=false"><view class="drawer" @click.stop><view class="drawer-head"><text @click="drawerVisible=false">取消</text><strong>确认缺货处置</strong><text @click="submit">{{submitting?'提交中':'确定'}}</text></view><view class="summary"><text>处理方式</text><strong>{{action===6?'缺货补货':'缺货不补'}}</strong><text>处理范围</text><strong>{{selected.length}}项 · {{selectedUnits}}扎</strong></view><text class="label">备注（选填）</text><textarea v-model="remark" maxlength="100" placeholder="补充本次未配货处置说明"/></view></view>
  <SessionDatePicker v-model="date" v-model:visible="sessionPickerVisible" @confirm="changeSession"/>
</view></template>

<style scoped lang="scss">
.page{min-height:100vh;padding:24rpx 24rpx 190rpx}.overview{display:flex;align-items:flex-end;justify-content:space-between;padding:24rpx;border-radius:22rpx;background:var(--wms-primary-700);color:#fff}.overview view{display:flex;align-items:baseline;gap:8rpx}.overview text{font-size:22rpx;opacity:.84}.overview strong{font-size:48rpx}.overview small{font-size:21rpx}.filters{display:grid;grid-template-columns:1fr 1fr 150rpx;gap:10rpx;margin-top:18rpx}.search,.zone-filter{display:flex;height:66rpx;align-items:center;padding:0 15rpx;border-radius:14rpx;background:#fff;font-size:21rpx}.search input{width:100%;font-size:21rpx}.zone-filter{justify-content:space-between;color:var(--wms-primary-700)}.down{width:10rpx;height:10rpx;border-right:2rpx solid currentColor;border-bottom:2rpx solid currentColor;transform:rotate(45deg) translateY(-3rpx)}.list-head,.row{display:grid;grid-template-columns:42rpx minmax(0,1fr) 72rpx 150rpx;align-items:center}.list-head{height:64rpx;margin-top:18rpx;color:var(--wms-text-secondary);font-size:20rpx}.list-head text:nth-last-child(-n+2){text-align:center}.rows{display:flex;flex-direction:column;gap:12rpx}.row{min-height:104rpx;padding:14rpx 8rpx;border:2rpx solid transparent;border-radius:18rpx;background:#fff}.row.selected{border-color:var(--wms-primary-700);background:var(--wms-surface-soft)}.check{display:flex;width:27rpx;height:27rpx;align-items:center;justify-content:center;border:2rpx solid #aebbb8;border-radius:6rpx;color:#fff;font-size:17rpx}.check.checked{border-color:var(--wms-primary-700);background:var(--wms-primary-700)}.product{min-width:0}.product strong,.product small,.shelf strong,.shelf small{display:block}.product strong{overflow:hidden;font-size:23rpx;white-space:nowrap;text-overflow:ellipsis}.product strong text{margin-right:8rpx;padding:3rpx 8rpx;border-radius:6rpx;background:#e4f3ec;color:var(--wms-primary-700);font-size:18rpx}.product small{overflow:hidden;margin-top:8rpx;color:var(--wms-text-secondary);font-size:19rpx;white-space:nowrap;text-overflow:ellipsis}.row>b{color:var(--wms-danger);font-size:28rpx;text-align:center}.shelf{text-align:center}.shelf strong{font-size:21rpx}.shelf small{margin-top:6rpx;color:var(--wms-text-secondary);font-size:18rpx}.bottom{position:fixed;right:0;bottom:0;left:0;z-index:10;padding:12rpx 24rpx calc(18rpx + env(safe-area-inset-bottom));border-top:1rpx solid var(--wms-border);background:#fff}.selection{margin-bottom:9rpx;color:var(--wms-text-secondary);font-size:19rpx}.actions{display:grid;grid-template-columns:1fr 1fr;gap:14rpx}.actions button{height:68rpx;margin:0;border:0;border-radius:14rpx;background:var(--wms-primary-700);color:#fff;font-size:23rpx;line-height:68rpx}.actions .danger{background:var(--wms-danger)}.mask{position:fixed;z-index:30;inset:0;display:flex;align-items:flex-end;background:rgba(15,28,26,.42)}.drawer{box-sizing:border-box;width:100%;padding:24rpx 24rpx calc(30rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:#fff}.drawer-head{display:grid;grid-template-columns:100rpx 1fr 100rpx;align-items:center}.drawer-head strong{text-align:center}.drawer-head text{color:var(--wms-text-secondary);font-size:22rpx}.drawer-head text:last-child{color:var(--wms-primary-700);text-align:right}.summary{display:grid;grid-template-columns:1fr 1fr;gap:15rpx;margin-top:28rpx;padding:22rpx;border-radius:16rpx;background:var(--wms-surface-soft)}.summary text{color:var(--wms-text-secondary);font-size:21rpx}.summary strong{text-align:right;font-size:22rpx}.label{display:block;margin:24rpx 0 10rpx;font-size:22rpx}.drawer textarea{box-sizing:border-box;width:100%;height:150rpx;padding:16rpx;border:1rpx solid var(--wms-border);border-radius:14rpx;font-size:22rpx}
.zone-drawer{max-height:86vh}.zone-head{display:flex;align-items:center;justify-content:space-between}.zone-head strong{font-size:29rpx}.zone-head text{color:var(--wms-primary-700);font-size:23rpx}.zone-scroll{max-height:72vh;margin-top:22rpx}.zone-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14rpx}.zone-grid view{height:70rpx;border:2rpx solid transparent;border-radius:9rpx;background:#f0f2f2;font-size:22rpx;line-height:70rpx;text-align:center}.zone-grid .active{border-color:var(--wms-primary-700);background:var(--wms-surface-soft);color:var(--wms-primary-700)}
.product strong text{margin-right:0;margin-left:8rpx}
</style>
